function useDemoState() {
  const [state, setState] = useState<DemoState>(INITIAL_STATE);
  const [hydrated, setHydrated] = useState(false);
  useEffect(() => {
    try { const saved = localStorage.getItem("quorum-demo-state"); if (saved) setState({ ...INITIAL_STATE, ...JSON.parse(saved) }); } catch {}
    setHydrated(true);
  }, []);
  useEffect(() => { if (hydrated) localStorage.setItem("quorum-demo-state", JSON.stringify(state)); }, [state, hydrated]);
  const update = (patch: Partial<DemoState>) => setState(previous => ({ ...previous, ...patch }));
  const reset = () => { setState(INITIAL_STATE); localStorage.removeItem("quorum-demo-state"); };
  return { state, update, reset, hydrated };
}

