function Nominations({ state, update }: { state: DemoState; update: (p: Partial<DemoState>)=>void }) {
  const [statement,setStatement]=useState(state.nominationStatement); const [manifesto,setManifesto]=useState(state.nominationManifesto); const [agree,setAgree]=useState(false); const [error,setError]=useState("");
  const submit=()=>{if(statement.trim().length<20||manifesto.trim().length<100||!agree){setError("Add a complete statement, a manifesto of at least 100 characters, and confirm the declaration.");return;} update({nominationStatus:"pending",nominationStatement:statement,nominationManifesto:manifesto,nominatedAt:"Sep 19, 2026 · 10:42 AM"});};
  if(state.nominationStatus!=="none") return <><PageHeader eyebrow="Nomination centre" title="Your nomination" description="Track the review status for this election cycle."/><div className={`${cardClass} mt-8 overflow-hidden`}><div className="bg-[#1b1422] p-6 text-white"><div className="flex items-center justify-between gap-4"><div><StatusBadge tone={state.nominationStatus==="approved"?"green":state.nominationStatus==="rejected"?"red":"gold"}>{state.nominationStatus[0].toUpperCase()+state.nominationStatus.slice(1)}</StatusBadge><h2 className="display mt-4 text-3xl font-bold">Computer Science Department Representative</h2><p className="mt-2 text-[#bdb3c2]">Submitted {state.nominatedAt}</p></div><FileCheck2 size={44} className="text-[#d9ad5f]"/></div></div><div className="grid gap-7 p-6 lg:grid-cols-[1fr_.65fr]"><div><h3 className="font-bold">Candidacy statement</h3><p className="mt-2 text-[#5f5650]">{state.nominationStatement}</p><h3 className="mt-6 font-bold">Manifesto</h3><p className="mt-2 whitespace-pre-line leading-7 text-[#5f5650]">{state.nominationManifesto}</p></div><div className="rounded-2xl bg-[#f4efe6] p-5"><h3 className="font-bold">Review timeline</h3><div className="mt-5 space-y-5 text-sm"><div className="flex gap-3"><CheckCircle2 className="text-[#17745a]" size={19}/><div><strong>Submitted</strong><p className="text-[#6e665f]">Eligibility confirmed</p></div></div><div className="flex gap-3"><Clock3 className="text-[#a27022]" size={19}/><div><strong>Administrative review</strong><p className="text-[#6e665f]">Usually within one working day</p></div></div><div className="flex gap-3 opacity-50"><Sparkles size={19}/><div><strong>Candidate profile published</strong><p>After approval</p></div></div></div>{state.nominationStatus==="pending"&&<button onClick={()=>update({nominationStatus:"withdrawn"})} className="mt-7 text-sm font-bold text-[#a4382e]">Withdraw nomination</button>}</div></div></div></>;
  return <><PageHeader eyebrow="Nomination centre" title="Nominate yourself" description="You can stand in one ballot per election cycle. Your official profile details are attached automatically."/><div className="mt-8 grid gap-6 lg:grid-cols-[.72fr_1.28fr]"><aside className={`${cardClass} h-fit p-6`}><div className="flex items-center gap-4"><div className="grid size-16 place-items-center rounded-2xl bg-[#8f2f43] text-xl font-bold text-white">NA</div><div><h2 className="display text-2xl font-bold">Nada Alahmad</h2><p className="text-sm text-[#6e665f]">ID #20260925</p></div></div><dl className="mt-6 grid gap-4 text-sm"><div><dt className="text-[#837a72]">Department</dt><dd className="font-semibold">Computer Science</dd></div><div><dt className="text-[#837a72]">Class year</dt><dd className="font-semibold">Year 4</dd></div><div><dt className="text-[#837a72]">Registered clubs</dt><dd className="font-semibold">Robotics Society · ACM Chapter</dd></div></dl><div className="mt-6 flex gap-2 rounded-xl bg-[#e5f4ef] p-3 text-sm text-[#17604c]"><UserCheck className="shrink-0" size={18}/>Eligible for this ballot</div></aside><form onSubmit={e=>{e.preventDefault();submit();}} className={`${cardClass} p-6 sm:p-8`}><div className="flex items-start justify-between gap-4"><div><StatusBadge tone="violet">Nominations open</StatusBadge><h2 className="display mt-3 text-3xl font-bold">Computer Science Department Representative</h2><p className="mt-1 text-sm text-[#6e665f]">Closes Sep 21 · 6:00 PM</p></div><Megaphone className="text-[#8f2f43]"/></div><label className="mt-7 block font-semibold">Candidacy statement <span className="font-normal text-[#766e67]">({statement.length}/140)</span><input maxLength={140} value={statement} onChange={e=>setStatement(e.target.value)} placeholder="One clear sentence describing your candidacy" className={fieldClass}/></label><label className="mt-5 block font-semibold">Manifesto <span className="font-normal text-[#766e67]">({manifesto.length}/2000)</span><textarea maxLength={2000} rows={9} value={manifesto} onChange={e=>setManifesto(e.target.value)} placeholder="Explain your priorities, commitments and how you will report progress." className={fieldClass}/></label><label className="mt-5 flex items-start gap-3 rounded-xl bg-[#f5f1e8] p-4 text-sm"><input type="checkbox" checked={agree} onChange={e=>setAgree(e.target.checked)} className="mt-1 size-4 accent-[#8f2f43]"/><span>I confirm that this manifesto is my own submission and may be published if approved.</span></label>{error&&<p role="alert" className="mt-4 rounded-xl bg-red-50 p-3 text-sm text-red-800">{error}</p>}<div className="mt-6 flex justify-end"><button type="submit" className={primaryButton}>Review and submit <ArrowRight size={17}/></button></div></form></div></>;
}

